    # paint: for each line, for each marker offset, ray across gap perpendicular
    for (lr,lc0,lc1) in [A,B]:
        for (mr,mc_,oa,ob) in offs:
            if oa is None: continue
            # target line: the other one
            tgt=A if (lr,lc0,lc1)==B else B
            tr,tc0,tc1=tgt
            if typ=='h':
                step=-1 if tr>lr else 1
                rr=tr+step
                painted=False
                while 0<=rr<H:
