from collections import Counter
def find_segments(g,color):
    H,W=len(g),len(g[0]); segs=[]
    for j in range(W):
        i=0
        while i<H:
            k=i
            while k<H and g[k][j]==color: k+=1
            if k-i>=2: segs.append(('V',i,k-1,j))
            i+=1
    for i in range(H):
        j=0
        while j<W:
            k=j
            while k<W and g[i][k]==color: k+=1
            if k-j>=2: segs.append(('H',i,j,k-1))
            j+=1
    return segs

