from collections import Counter
import json

def f(g):
    H=len(g); W=len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # walls: color forming straight >=2 runs; dots: rarest other color
    order=[v for v in sorted(cnt,key=lambda x:cnt[x])]
    dot=min(order[1:],key=lambda x:cnt[x]) if len(order)>2 else None
    others=[v for v in cnt if v not in (bg,dot)]
    wall=others[0] if others else None
    res=[r[:] for r in g]
    def cast(wr,wc,d,rng_start,rng_end):
        step=d
        j=rng_start
        while 0<=j<rng_end and (d==1 or (d==-1 and j>0)):
            pass
        return None
    def do_cast(start,end,dotcol):
        # start/end columns/rows of wall run; d=+1 or -1
        j=start
        while j<=end:
            val=g[start][j]
            if val==dotcol:
                res[start][j]=4
                break
            res[start][j]=wall
            j+=1
    # find wall runs
    runs=[]
    for i in range(H):
        j=0
        while j<W:
            k=j
            while k<W and g[i][k]==wall: k+=1
            if k-j>=2: runs.append(('H',i,j,k-1))
            j=k
    for j in range(W):
        i=0
        while i<H:
            k=i
            while k<H and g[k][j]==wall: k+=1
            if k-i>=2: runs.append(('V',j,i,k-1))
            i+=1
    if not runs: return g
    # determine direction per run: for 'H' walls, fill vertically both up and down from wall cells?
    # Demo5: V wall col14 rows3-7 -> rays leftward (toward interior). V wall col0 rows17-21 -> rays rightward.
    # H wall row0 cols0-3 -> rays downward. H wall row21 cols6-9 -> rays upward.
    out=[r[:] for r in g]
    for typ,pos,a,b in runs:
        if typ=='H':
            for j in range(a,b+1):
                for di in (-1,1):
                    i=a+di
                    while 0<=i<H:
                        if out[i][j]==dotcol:
                            out[i][j]=4; break
                        out[i][j]=wall
                        i+=di
        else:
            for i in range(a,b+1):
                for dj in (-1,1):
                    j=pos+dj
                    while 0<=j<W:
                        if out[i][j]==dotcol:
                            out[i][j]=4; break
                        out[i][j]=wall
                        j+=dj
    return out

